head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/controlResize.js"); // 화면 리사이징

scwin.gAcptNo;
scwin.gViewerStat = "P"; // 처리시 뷰=P,  조회시 뷰=R,  사후심사 A
scwin.gIsurCd;
scwin.gSndlocTpCd;
scwin.gExmptYn; //면제대상여부(bypass)

scwin.gDate;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보 
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

scwin.vScrenID = 'ULDSTF11000.gfm'; //유가 공시부-담당자 검토

scwin.search_yn = false;
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {

	//----W-Craft WebSquare 변환 확인: showObj----//
    showObj(panel_2, false);

	//----W-Craft WebSquare 변환 확인: showObj----//
    showObj(panel_3, false);
    var strDepCd = js_dep_cd.substring(0, 2);

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 보여준다.
    //if (js_dep_cd.substring(0,2) == '26'  || js_dep_cd.substring(0,2) == '34' ) {
    //if (js_dep_cd.substring(0,1) == '2'  || js_dep_cd.substring(0,2) == '34' ) {
    if (strDepCd == '24' || strDepCd == '25' || strDepCd == '2B') {
        //24=채권상장, 25=상장심사부, 2B=증권상품

	//----W-Craft WebSquare 변환 확인: showObj----//
        showObj(panel_2, true);

	//----W-Craft WebSquare 변환 확인: showObj----//
        showObj(panel_3, true);
    } else if (strDepCd == '26' || strDepCd == '34') {
        //공시팀인경우 당번만 보여준다 2013.03.26

	//----W-Craft WebSquare 변환 확인: showObj----//
        showObj(panel_3, true); //담당자
        if (scwin.gDepCd == '2610' || scwin.gDepCd == '3410') {
            //공시제도팀의 경우 팀장, 팀원 모두 공시제도팀공시만 볼 수 있다. 20210312 - IT운영팀

	//----W-Craft WebSquare 변환 확인: showObj----//
            showObj(panel_2, false); //팀장			
        } else {
            if (scwin.gJobTitle == '09' || scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y') {

	//----W-Craft WebSquare 변환 확인: showObj----//
                showObj(panel_2, true); //팀장				
            }
        }
    }

    //처음엔 전체 체크
    chb_stat_all.checked = false;
    chb_stat_00.checked = true;
    chb_stat_02.checked = true;
    chb_stat_01.checked = true;
    chb_stat_10.checked = false;
    chb_stat_20.checked = false;
    chb_stat_30.checked = false;
    chb_stat_35.checked = false;
    chb_stat_40.checked = false;
    chb_reg.checked = false;

    //처음엔 전체 체크
    chb_affstat_all.checked = false;
    chb_affstat_00.checked = true;
    chb_affstat_01.checked = true;
    chb_affstat_10.checked = false;
    chb_affstat_20.checked = false;
    chb_affstat_30.checked = false;
    chb_affstat_40.checked = false;


    // 현재날짜 셋팅	

	//----W-Craft WebSquare 변환 확인: cGetToday----//
    scwin.gDate = cGetToday("yyyymmdd");
    edt_SrchDay.setValue(scwin.gDate);

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=getDepUpCodeOrg"+
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + js_dep_cd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + js_dep_cd;
    dts_emp.Reset();
};
scwin.fn_DepListLoadComplete = function() {

	//----W-Craft WebSquare 변환 확인: setObjectValue----//
    setObjectValue(cmb_TeamList, js_dep_cd);
    // 부서코드 가져온후에  초기검색
    scwin.fn_InitSearch();
};


// 화면 로딩시 디폴트 검색
scwin.fn_InitSearch = function() {
    scwin.fn_Reload('N');
};
scwin.fn_Reload = function(pReload) {
    scwin.fn_CheckCond(pReload);

	//----W-Craft WebSquare 변환 확인: setTimeout----//
    setTimeout("fn_Reload('Y')", 30000); // 1초 = 1000 , 30초 = 30000
};


// 담당자 검토대상  목록검색 : 사용자 클릭 -->
scwin.fn_CheckCond = function(pReload) {
    // 일자 체크

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (com.wconv.length(getObjectValue(edt_SrchDay)) < 8) {
        alert("일자 올바르게 입력하십시오.");

	//----W-Craft WebSquare 변환 확인: focus----//
        edt_SrchDay.focus();
        return;
    }
    var vStatCnt = 0;
    if (chb_stat_00.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_02.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_01.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_10.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_20.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_30.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_35.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_40.checked == true) {
        vStatCnt++;
    }
    if (chb_reg.checked == true) {
        vStatCnt++;
    }
    var vAffStatCnt = 0;
    if (chb_affstat_00.checked == true) {
        vAffStatCnt++;
    }
    if (chb_affstat_01.checked == true) {
        vAffStatCnt++;
    }
    if (chb_affstat_10.checked == true) {
        vAffStatCnt++;
    }
    if (chb_affstat_20.checked == true) {
        vAffStatCnt++;
    }
    if (chb_affstat_30.checked == true) {
        vAffStatCnt++;
    }
    if (chb_affstat_40.checked == true) {
        vAffStatCnt++;
    }

    // 처리상태 1개 이상 체크
    if (vStatCnt < 1 && vAffStatCnt < 1) {
        alert("처리현황 또는 사후심사현황을 한개 이상  선택하십시요.");
        return;
    }

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    scwin.gDate = getObjectValue(edt_SrchDay);

    // 유가 공시팀(26**), 코스닥 공시팀(34**) =>  선택부서로
    //if (js_dep_cd.substring(0,2) == '26'  || js_dep_cd.substring(0,2) == '34' ) {
    if (js_dep_cd.substring(0, 1) == '2' || js_dep_cd.substring(0, 2) == '34') {

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        scwin.gDepCd = getObjectValue(cmb_TeamList);

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        scwin.gEmpNo = getObjectValue(cmb_EmpList);
    } else {
        scwin.gDepCd = ""; // 부서코드 없음 => 전체	
        scwin.gEmpNo = "";
    }
    scwin.fn_Search(pReload);
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};



// 담당자 검토대상  목록검색 : 사용자 클릭 -->
scwin.fn_Search = function(pReload) {

	//----W-Craft WebSquare 변환 확인: ShowWin_yn----//
    ShowWin_yn(grd_Grid, scwin.search_yn);

    /******************************************************************
    	2009.09.01 채권공시관련 - 채권상장팀이면 시장구분을 '4'로 셋팅
    ******************************************************************/
    if (js_bond_yn == "Y") {
        scwin.gLdMktTp = "4";
    }
    var url = "/DisclosureStudyAffact.do?method=listDisclosureStudyAffact&inputMessageId=DSCLSTUDYCOND_AFF_IN" + "&outputMessageId=DSCLSTUDYLIST_AFF_OUT" + "&ACPT_DATE=" + scwin.gDate + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LD_MKT_TP=" + scwin.gLdMktTp + "&STAT_00=" + scwin.getChkValue(chb_stat_00) + "&STAT_02=" + scwin.getChkValue(chb_stat_02) + "&STAT_01=" + scwin.getChkValue(chb_stat_01) + "&STAT_10=" + scwin.getChkValue(chb_stat_10) + "&STAT_20=" + scwin.getChkValue(chb_stat_20) + "&STAT_30=" + scwin.getChkValue(chb_stat_30) + "&STAT_35=" + scwin.getChkValue(chb_stat_35) + "&STAT_40=" + scwin.getChkValue(chb_stat_40) + "&STAT_REG=" + scwin.getChkValue(chb_reg) + "&AFF_STAT_00=" + scwin.getChkValue(chb_affstat_00) + "&AFF_STAT_01=" + scwin.getChkValue(chb_affstat_01) + "&AFF_STAT_10=" + scwin.getChkValue(chb_affstat_10) + "&AFF_STAT_20=" + scwin.getChkValue(chb_affstat_20) + "&AFF_STAT_30=" + scwin.getChkValue(chb_affstat_30) + "&AFF_STAT_40=" + scwin.getChkValue(chb_affstat_40) + "&UP_DEP_CD=" + js_belngdepcd;
    if (pReload != 'Y') {
        //자동refresh일때는 로그 없앰
        url = url + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    }

    //grd_Grid.Redraw ="false";
    dts_DsclStudyList.DataID = encodeURI(url);
    dts_DsclStudyList.reset();

    /*
    var fFrame = frame.Provider("/pageIndex").selPageID;
    var fname = frame.FrameID;
    if (fFrame == fname) {
    	ShowWin(grd_Grid);
    }
    */
};



// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {

	//----W-Craft WebSquare 변환 확인: NameString----//
    scwin.gAcptNo = dts_DsclStudyList.NameString(eval(obj), "ACPT_NO");

	//----W-Craft WebSquare 변환 확인: NameString----//
    scwin.gIsurCd = dts_DsclStudyList.NameString(eval(obj), "ISUR_CD");

	//----W-Craft WebSquare 변환 확인: NameString----//
    scwin.gExmptYn = dts_DsclStudyList.NameString(eval(obj), "EXMPT_OBJ_DISCLS_YN"); //bypass 여부 
};


//처리현황(전체)
scwin.fn_checkAll = function() {
    // 전체가 체크일때 
    if (chb_stat_all.checked == true) {
        chb_stat_00.checked = true;
        chb_stat_02.checked = true;
        chb_stat_01.checked = true;
        chb_stat_10.checked = true;
        chb_stat_20.checked = true;
        chb_stat_30.checked = true;
        chb_stat_35.checked = true;
        chb_stat_40.checked = true;
        chb_reg.checked = true;
    } else {
        chb_stat_00.checked = false;
        chb_stat_02.checked = false;
        chb_stat_01.checked = false;
        chb_stat_10.checked = false;
        chb_stat_20.checked = false;
        chb_stat_30.checked = false;
        chb_stat_35.checked = false;
        chb_stat_40.checked = false;
        chb_reg.checked = false;
    }
};


//처리현황(전체)
scwin.fn_checkAll2 = function() {
    // 전체가 체크일때 
    if (chb_affstat_all.checked == true) {
        chb_affstat_00.checked = true;
        chb_affstat_01.checked = true;
        chb_affstat_10.checked = true;
        chb_affstat_20.checked = true;
        chb_affstat_30.checked = true;
        chb_affstat_40.checked = true;
    } else {
        chb_affstat_00.checked = false;
        chb_affstat_01.checked = false;
        chb_affstat_10.checked = false;
        chb_affstat_20.checked = false;
        chb_affstat_30.checked = false;
        chb_affstat_40.checked = false;
    }
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (scwin.gExmptYn == 'Y') {
        //bypass 일경우 뷰어 상태는 'A'여야 함 'A'는 사후심사 
        scwin.gViewerStat = 'A';
    } else {
        scwin.gViewerStat = 'P';
    }
    if (colid == "DOC_TITLE") {

	//----W-Craft WebSquare 변환 확인: fn_OpenNoDisclViewer----//
        fn_OpenNoDisclViewer(scwin.gAcptNo, scwin.gViewerStat, js_emp_no, js_dep_cd, js_jobtitl, js_duty, js_duty_chrg, 'P', dts_DutyStatus); //2013.05.14
        //fn_OpenNoDisclViewer(gAcptNo, gViewerStat);
    } else if (colid == "ACPT_DDTM") {

	//----W-Craft WebSquare 변환 확인: fn_OpenDisclAllList----//
        fn_OpenDisclAllList();
    } else if (colid == "COM_ABBRV") {

	//----W-Craft WebSquare 변환 확인: fn_PopupCorpInfo----//
        fn_PopupCorpInfo();
    }
};
scwin.chb_stat_all_onclick = function(index, checked, value) {
    scwin.fn_checkAll();
};
scwin.chb_affstat_all_onclick = function(index, checked, value) {
    scwin.fn_checkAll2();
};
scwin.btn_Search_onclick = function(e) {
    scwin.fn_CheckCond('N');
    scwin.search_yn = true;
};
scwin.dts_dep_OnLoadError = function() {

	//----W-Craft WebSquare 변환 확인: alert_error----//
    alert_error(dts_dep);
};
scwin.dts_emp_OnLoadError = function() {

	//----W-Craft WebSquare 변환 확인: alert_error----//
    alert_error(dts_emp);
};
scwin.dts_DutyStatus_OnLoadError = function() {

	//----W-Craft WebSquare 변환 확인: alert_error----//
    alert_error(dts_DutyStatus);
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    scwin.fn_DepListLoadComplete();
};
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_EmpList, js_emp_no) ;	// 로그인사람을 디폴트 선택시

};
scwin.cmb_TeamList_OnSelChange = function() {

	//----W-Craft WebSquare 변환 확인: ValueOfIndex----//
    scwin.gDepCd = cmb_TeamList.ValueOfIndex("VALUE", cmb_TeamList.Index);
    if (scwin.gDepCd == '') {

	//----W-Craft WebSquare 변환 확인: setObjectValue----//
        setObjectValue(cmb_EmpList, '');
    }

	//----W-Craft WebSquare 변환 확인: Filter----//
    dts_emp.UseFilter = true;

	//----W-Craft WebSquare 변환 확인: Filter----//
    dts_emp.Filter();
    dts_emp.SortExpr = "DEP_CD";
    dts_emp.Sort();
};

	//----W-Craft WebSquare 변환 확인: Filter----//
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        if (dts_emp.NameValue(row, "dep_cd") == scwin.gDepCd ||

	//----W-Craft WebSquare 변환 확인: NameValue----//
            dts_emp.NameValue(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.dts_DsclStudyList_OnLoadError = function() {

	//----W-Craft WebSquare 변환 확인: alert_error----//
    alert_error(dts_DsclStudyList);


    /*
    var fFrame = frame.Provider("../").ActiveFrame.FrameID;
    var fname = frame.FrameID;
    if (fFrame == fname) {

	//----W-Craft WebSquare 변환 확인: CloseWin----//
    	CloseWin('', grd_Grid); 
    }
    */

	//----W-Craft WebSquare 변환 확인: CloseWin----//
    CloseWin(0, grd_Grid);
    scwin.search_yn = false;
};
scwin.dts_DsclStudyList_OnLoadCompleted = function(rowcount) {
    if (dts_DsclStudyList.errorMsg) {
        alert(dts_DsclStudyList.errorMsg);
    } else {

	//----W-Craft WebSquare 변환 확인: FillGridHeaderTotalCnt----//
        FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    //grd_Grid.Redraw ="true";
    /*
    var fFrame = frame.Provider("../").ActiveFrame.FrameID;
    var fname = frame.FrameID;
    if (fFrame == fname) {

	//----W-Craft WebSquare 변환 확인: CloseWin----//
    	CloseWin(rowcount, grd_Grid); 
    }*/


	//----W-Craft WebSquare 변환 확인: CloseWin----//
    CloseWin(rowcount, grd_Grid);
    scwin.search_yn = false;
};
scwin.btn_Excel_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: doLogSave----//
    doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);

	//----W-Craft WebSquare 변환 확인: GridToExcel----//
    grd_Grid.GridToExcel(" 담당자검토대상 목록", "", "2");
};
scwin.img_Cal_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: popUpCalendar2----//
    popUpCalendar2(edt_SrchDay);
};
scwin.gform_onload = function() {
    // 리로드 시 스크립트 오류로 인해 패치함


    scwin.fn_SetCode();

    // 패널라운드 처리

	//----W-Craft WebSquare 변환 확인: PanelToGroupBox----//
    PanelToGroupBox(panel_1);

    // 가우스헤더 셋팅
    //dts_StudyCond.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLSTUDYCOND_IN";
    //dts_StudyCond.reset();	
};
